mapper.select:
SELECT p.id, p.spu_code, p.name, p.shelf_id, p.main_image, p.description, p.price, p.status, p.alert_template_id, p.created_at, p.updated_at FROM product p LEFT JOIN warehouse_shelf ws ON p.shelf_id = ws.id AND ws.deleted = 0
p.deleted = 0
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.spu_code LIKE CONCAT('%', #{keyword}, '%'))
AND p.shelf_id = #{shelfId}
AND p.status = #{status}
ORDER BY p.id DESC
